import{_ as t,o as d,c as o,ag as c}from"./chunks/framework.C9sp7nFj.js";const u=JSON.parse('{"title":"Admin API","description":"","frontmatter":{},"headers":[],"relativePath":"reference/api.md","filePath":"reference/api.md","lastUpdated":1779875348000}'),r={name:"reference/api.md"};function a(i,e,s,n,p,l){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="admin-api" tabindex="-1">Admin API <a class="header-anchor" href="#admin-api" aria-label="Permalink to &quot;Admin API&quot;">​</a></h1><p>The admin API lives under <code>/api/v1/*</code> and is consumed by the web UI. You can also call it programmatically — either with a session cookie (after logging in) or with an API token that holds the right capability.</p><p>This page is a high-level map. For the consumer-facing read endpoint, see <a href="./consuming-data">Consuming data</a>.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>Two equivalent options:</p><ul><li><strong>Session cookie</strong> — set automatically after you log in to the UI. Useful when scripting against your own browser session.</li><li><strong>Bearer token</strong> — <code>Authorization: Bearer pika_...</code>. The token must have a capability that covers the requested operation.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Token capabilities for admin operations are different from path scopes used on <code>/data/*</code>. A token holds a list of capabilities (<code>files.read</code>, <code>settings.manage</code>, …). The list is set when the token is created.</p></div><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Capability</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/v1/info</code></td><td><em>(public)</em></td><td>Server metadata, current user, capabilities, raw mounts.</td></tr><tr><td><code>GET</code></td><td><code>/healthz</code></td><td><em>(public)</em></td><td>Health probe.</td></tr><tr><td><code>GET</code>,<code>POST</code>,<code>PATCH</code>,<code>DELETE</code></td><td><code>/api/v1/users[/...]</code></td><td><code>users.manage</code></td><td>User CRUD.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/users-kick/{username}</code></td><td><code>users.manage</code></td><td>Force-logout a user (invalidates their sessions).</td></tr><tr><td><code>GET</code>,<code>POST</code>,<code>PATCH</code>,<code>DELETE</code></td><td><code>/api/v1/permissions[/...]</code></td><td><code>permissions.manage</code></td><td>Permission bundle CRUD.</td></tr><tr><td><code>GET</code>,<code>PUT</code></td><td><code>/api/v1/user-permissions/{username}</code></td><td><code>permissions.manage</code></td><td>Assign permission bundles to a user.</td></tr><tr><td><code>GET</code>,<code>POST</code>,<code>DELETE</code></td><td><code>/api/v1/folder[/...]</code></td><td><code>files.read</code>/<code>write</code></td><td>Folder navigation, create, delete.</td></tr><tr><td><code>GET</code>,<code>POST</code>,<code>DELETE</code></td><td><code>/api/v1/file/{path}</code></td><td><code>files.read</code>/<code>write</code></td><td>Config file CRUD. Supports <code>?variant=</code> and <code>?version=</code>.</td></tr><tr><td><code>GET</code>,<code>PATCH</code></td><td><code>/api/v1/versions/{path}[/{n}]</code></td><td><code>files.read</code>/<code>write</code></td><td>List versions; set / clear semver constraint on a specific version.</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/variants/{path}</code></td><td><code>files.read</code></td><td>List variants of a file.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/render/{path}</code></td><td><code>files.read</code></td><td>Resolve inheritance / variants — returns the merged document.</td></tr><tr><td><code>GET</code>,<code>POST</code>,<code>DELETE</code>,<code>PATCH</code></td><td><code>/api/v1/tokens[/{id}]</code></td><td><code>tokens.manage</code></td><td>API token CRUD.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/convert</code></td><td><code>files.read</code></td><td>Convert content between JSON / YAML / TOML.</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/search?q=...</code></td><td><code>files.read</code></td><td>Full-text search across configs (Server-Sent Events stream).</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/key/status</code></td><td><em>(public)</em></td><td>Server encryption-key state (initialized / unlocked).</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/key/initialize</code></td><td><code>settings.manage</code></td><td>Opt in to at-rest encryption (first-time setup of the server key).</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/key/unlock</code></td><td><code>settings.manage</code></td><td>Unlock the server after a restart by supplying the master key.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/key/lock</code></td><td><code>settings.manage</code></td><td>Manually re-lock the server without restarting.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/key/rotate</code></td><td><code>settings.manage</code></td><td>Rotate the server encryption key (current → new).</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/tls-generate</code></td><td><code>settings.manage</code></td><td>Generate a TLS certificate / key pair.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/ssh-keygen</code></td><td><code>settings.manage</code></td><td>Generate an SSH key pair.</td></tr><tr><td><code>GET</code>,<code>POST</code></td><td><code>/api/v1/settings</code></td><td><code>settings.manage</code></td><td>Read / patch the entire settings document.</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/cluster/status</code></td><td><code>settings.manage</code></td><td>Runtime cluster role, quorum, leader and visible alan peers.</td></tr><tr><td><code>GET</code>,<code>POST</code></td><td><code>/api/v1/backup[/info]</code></td><td><code>settings.manage</code></td><td>Export / inspect / import a full backup archive.</td></tr><tr><td><code>GET</code>,<code>PUT</code>,<code>DELETE</code></td><td><code>/api/v1/raw/{prefix}/{path}</code></td><td><code>raw.read</code>/<code>write</code></td><td>Raw FS browsing (UI, session-auth side).</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/raw-mkdir/{prefix}/{path}</code></td><td><code>raw.write</code></td><td>Create a folder on a raw mount.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/raw-rename</code></td><td><code>raw.write</code></td><td>Rename a file on a raw mount.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/raw-copy</code></td><td><code>raw.write</code></td><td>Copy a file (possibly cross-mount).</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/raw-move</code></td><td><code>raw.write</code></td><td>Move a file (possibly cross-mount).</td></tr><tr><td><code>GET</code>,<code>PUT</code></td><td><code>/api/v1/registries</code></td><td><code>registry.read</code>/<code>registry.admin</code></td><td>Read or replace the namespace/repository tree.</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/registries/{type}/{ns}/{repo}/stats</code></td><td><code>registry.read</code></td><td>Registry storage/package statistics.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/registries/{type}/{ns}/{repo}/purge</code></td><td><code>registry.admin</code></td><td>Purge remote registry cache.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/registries/{type}/{ns}/{repo}/test-upstream</code></td><td><code>registry.admin</code></td><td>Probe a remote registry upstream.</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/external/{name}/paths</code></td><td><code>settings.manage</code></td><td>Browse paths in a configured external resource (Vault, Consul, …).</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/user-sync/status</code></td><td><code>settings.manage</code></td><td>Last-run report for every configured user-sync source.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/user-sync/run/{id}</code></td><td><code>settings.manage</code></td><td>Trigger a one-shot user-sync run.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/user-sync/test/{id}</code></td><td><code>settings.manage</code></td><td>Dry-run a user-sync source — no writes performed.</td></tr></tbody></table><h2 id="public-consumer-endpoints" tabindex="-1">Public consumer endpoints <a class="header-anchor" href="#public-consumer-endpoints" aria-label="Permalink to &quot;Public consumer endpoints&quot;">​</a></h2><p>These are reachable on both the admin port (with token) and the public port (without):</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/data/{path}</code></td><td>Resolved config — see <a href="./consuming-data">Consuming data</a>.</td></tr></tbody></table><p>| <code>GET</code> | <code>/healthz</code> | Health probe. |</p><p>These data-plane endpoints are reachable on the admin port and require a token or UI session unless you publish them through a proxy graph:</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead></table><p>| <code>GET</code>,<code>HEAD</code>,<code>OPTIONS</code> | <code>/cdn/npm/{namespace}/{repo}/{package[@version]}/{file...}</code> | Authenticated direct NPM package CDN reads. Prefer a Proxy CDN listener for public CDN paths. |</p><h2 id="conventions" tabindex="-1">Conventions <a class="header-anchor" href="#conventions" aria-label="Permalink to &quot;Conventions&quot;">​</a></h2><ul><li>All write endpoints accept JSON request bodies and return JSON responses.</li><li>4xx responses include a <code>{ &quot;error&quot;: &quot;...&quot; }</code> body.</li><li>Long-running operations (search, backup) stream over Server-Sent Events.</li></ul><h2 id="discovering-endpoints" tabindex="-1">Discovering endpoints <a class="header-anchor" href="#discovering-endpoints" aria-label="Permalink to &quot;Discovering endpoints&quot;">​</a></h2><p><code>GET /api/v1/info</code> returns a description of the running server: version, configured features, the current user&#39;s capabilities, and the list of raw mounts. The web UI uses it on every load to decide which sections to render — you can use the same response to feature-detect when scripting.</p>',20)])])}const m=t(r,[["render",a]]);export{u as __pageData,m as default};
